<?php
declare(strict_types=1); require_once __DIR__.'/../config.php'; header('Content-Type: application/json; charset=utf-8');
function arr($v){return is_array($v)?$v:($v?[$v]:[]);} function escIn($a){return "'".implode("','",array_map('escape',array_filter(array_map('trim',$a))))."'";}
try{$start=substr((string)($_POST['startDate']??date('Y-m-d')),0,10);$end=substr((string)($_POST['endDate']??date('Y-m-d')),0,10);$status=arr($_POST['status']??[]);$bayar=arr($_POST['caraBayar']??[]);$where=["rp.kd_poli='IGDK'","rp.tgl_registrasi BETWEEN '".escape($start)."' AND '".escape($end)."'","rp.stts<>'Batal'"];if($status)$where[]='rp.stts IN ('.escIn($status).')';if($bayar)$where[]='rp.kd_pj IN ('.escIn($bayar).')';$w='WHERE '.implode(' AND ',$where);$sql="SELECT rp.no_rawat,p.no_rkm_medis,p.nm_pasien,p.jk,rp.tgl_registrasi,rp.jam_reg,d.nm_dokter,pj.png_jawab AS cara_bayar,rp.stts,CASE WHEN EXISTS(SELECT 1 FROM kamar_inap ki WHERE ki.no_rawat=rp.no_rawat) THEN 'Dirawat' ELSE rp.stts END AS status_igd,IFNULL(DATE_FORMAT(pak.tanggal,'%Y-%m-%d %H:%i:%s'),'-') AS askep,IFNULL(CONCAT(am.tanggal,' ',am.jam),'-') AS asmed,IFNULL(DATE_FORMAT(dt.tgl_kunjungan,'%Y-%m-%d %H:%i:%s'),'-') AS triase,IFNULL(DATE_FORMAT(ro.jam_peresepan,'%Y-%m-%d %H:%i:%s'),'-') AS resep_dokter FROM reg_periksa rp JOIN pasien p ON p.no_rkm_medis=rp.no_rkm_medis JOIN dokter d ON d.kd_dokter=rp.kd_dokter JOIN penjab pj ON pj.kd_pj=rp.kd_pj LEFT JOIN penilaian_awal_keperawatan_igd pak ON pak.no_rawat=rp.no_rawat LEFT JOIN asesmen_medis_igd am ON am.no_rawat=rp.no_rawat LEFT JOIN data_triase_igd dt ON dt.no_rawat=rp.no_rawat LEFT JOIN resep_obat ro ON ro.no_rawat=rp.no_rawat $w GROUP BY rp.no_rawat ORDER BY rp.tgl_registrasi DESC,rp.jam_reg DESC";$rows=q($sql);echo json_encode(['ok'=>true,'data'=>$rows]);}catch(Throwable $e){http_response_code(500);echo json_encode(['ok'=>false,'message'=>'Gagal mengambil data IGD.']);}

